package com.easy1auth.admin.web;
import com.easy1auth.admin.config.*; import com.easy1auth.audit.DeliveryService; import com.easy1auth.security.SecurityPolicyService; import com.easy1auth.admin.security.AdminTokenService; import com.easy1auth.adminaccess.AdminAccessService; import com.easy1auth.adminidentity.*; import com.easy1auth.tenant.*; import jakarta.servlet.http.HttpServletRequest; import org.junit.jupiter.api.Test; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.security.oauth2.jwt.Jwt; import java.time.*; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class AuthControllerTest{
 private final DeliveryService delivery=mock(DeliveryService.class); private final SecurityPolicyService security=mock(SecurityPolicyService.class); private final AdminIdentityService identities=mock(AdminIdentityService.class); private final AdminTokenService tokens=mock(AdminTokenService.class); private final TenantService tenants=mock(TenantService.class); private final AdminAccessService access=mock(AdminAccessService.class); private final RegistrationCodeService codes=mock(RegistrationCodeService.class); private final JavaMailSender mail=mock(JavaMailSender.class); private final AdminJwtProperties jwt=new AdminJwtProperties("issuer","audience","01234567890123456789012345678901",Duration.ofMinutes(15),Duration.ofDays(30)); private final AuthController controller=new AuthController(identities,tokens,tenants,jwt,access,codes,mail,new RegistrationProperties(true,"test@example.com"),security,delivery);
 @Test void registrationCreatesOwnerTenantAndSystemRolesInWorkflow(){UUID accountId=UUID.randomUUID(),tenantId=UUID.randomUUID();var account=new AdminAccount(accountId,"alice","a@example.com",null,"active",1,null,false,null,null,Instant.now(),Instant.now());when(identities.register(any(),any(),any(),any(),any(),any(),any())).thenReturn(new AuthenticatedAdmin(account,"refresh"));when(tenants.create(accountId,"alice的租户","basic")).thenReturn(new TenantSummary(tenantId,"alice的租户","active","basic","owner"));when(tenants.list(accountId)).thenReturn(List.of(new TenantSummary(tenantId,"alice的租户","active","basic","owner")));when(tokens.issue(account)).thenReturn("jwt");var request=mock(HttpServletRequest.class);var response=controller.register(new AuthController.RegisterRequest("a@example.com","Password1","123456","alice"),request);assertThat(response.data().user().currentTenantId()).isEqualTo(tenantId);verify(access).ensureDefaultRoles(tenantId);}
 @Test void bodylessLogoutInvalidatesAllAccountSessions(){UUID id=UUID.randomUUID();var principal=Jwt.withTokenValue("x").header("alg","none").subject(id.toString()).build();controller.logout(null,principal);verify(identities).logoutAllAndInvalidate(id);}
}
